type Progress = { topic: string; percent: number };
function isProgress(value: unknown): value is Progress {
  if (typeof value !== 'object' || value === null) return false;
  const item = value as Record<string, unknown>;
  return typeof item.topic === 'string' && typeof item.percent === 'number' && item.percent >= 0 && item.percent <= 100;
}
console.log(isProgress({ topic: 'Types', percent: 80 }));
